"""Count the free coordinates of the symmetric (equivariant) parameter subspace of the 62-60 design: orbits of the group generated by the
15 tree flips and the label negation acting on (W1 components, W2 entries, readouts), with sign tracking (orbits containing a coordinate
and its negative are forced to 0)."""
import numpy as np
from collections import defaultdict
from layer_lenses.designed_init import NODE_LEVEL, node_ancestors
LEVEL = NODE_LEVEL; leaves = list(range(15, 31)); internal = list(range(15))
def mirror(j, k):
    """image of node k under the flip at j (exchange of j's two subtrees; j and nodes outside its subtree fixed)."""
    if k == j or j not in node_ancestors(k): return k
    path = []; c = k
    while c != j: path.append((c - 1) % 2); c = (c - 1) // 2          # 0 = left child, 1 = right child, from k up to j
    c = j
    for d in reversed(path): c = 2 * c + 1 + (1 - d) if c == j and False else 2 * c + 1 + d
    # redo properly: flip only the first step below j
    c = j; first = True
    for d in reversed(path):
        c = 2 * c + 1 + ((1 - d) if first else d); first = False
    return c
rows = [(n, p) for n in range(31) for p in (1, -1)]                                  # row identities (probes: internal n; cues: leaf n)
units = [(n, b, s) for n in range(15) for (b, s) in ((1, 1), (1, -1), (-1, -1), (-1, 1))]
OFF = "off"; comps = list(range(31)) + [OFF]                                          # row components: 31 normals + the off-span scalar
coords = [("W1", r, k) for r in rows for k in comps] + [("W2", u, r) for u in units for r in rows] + [("a", u) for u in units]
idx = {c: i for i, c in enumerate(coords)}
def gen_flip(j):
    def row_map(r): n, p = r; return (mirror(j, n), -p if n == j else p)
    def comp_map(k): return (OFF, 1) if k == OFF else (mirror(j, k), -1 if k == j else 1)
    def unit_map(u): n, b, s = u; return (mirror(j, n), -b if n == j else b, s)
    out = {}
    for c in coords:
        if c[0] == "W1": k2, sg = comp_map(c[2]); out[c] = (("W1", row_map(c[1]), k2), sg)
        elif c[0] == "W2": out[c] = (("W2", unit_map(c[1]), row_map(c[2])), 1)
        else: out[c] = (("a", unit_map(c[1])), 1)
    return out
def gen_neg():
    def row_map(r): n, p = r; return (n, -p) if n >= 15 else (n, p)
    out = {}
    for c in coords:
        if c[0] == "W1": out[c] = (("W1", row_map(c[1]), c[2]), -1 if (c[2] != OFF and c[2] >= 15) else 1)
        elif c[0] == "W2": n, b, s = c[1]; out[c] = (("W2", (n, -b, -s), row_map(c[2])), 1)
        else: n, b, s = c[1]; out[c] = (("a", (n, -b, -s)), -1)
    return out
gens = [gen_flip(j) for j in range(15)] + [gen_neg()]
for g in gens: assert set(v[0] for v in g.values()) == set(coords)                   # each generator is a signed permutation of the coordinates
# signed union-find
parent = list(range(len(coords))); sign = [1] * len(coords); bad = set()
def find(i):
    if parent[i] == i: return i, 1
    r, s = find(parent[i]); parent[i], sign[i] = r, s * sign[i]; return r, sign[i]
def union(i, j, s):                                                                  # coordinate j = s * coordinate i
    ri, si = find(i); rj, sj = find(j)
    if ri == rj:
        if si * s != sj: bad.add(ri)
        return
    parent[rj] = ri; sign[rj] = si * s * sj
for g in gens:
    for c, (c2, s) in g.items(): union(idx[c], idx[c2], s)
roots = defaultdict(list)
for i, c in enumerate(coords): r, _ = find(i); roots[r].append(c)
# tally by coordinate family
def family(c):
    if c[0] == "a": return "readout"
    if c[0] == "W2": return "W2 probe column" if c[2][0] < 15 else "W2 cue column"
    r, k = c[1], c[2]; kind = "probe" if r[0] < 15 else "cue"
    if k == OFF: return f"W1 {kind} off-span"
    return f"W1 {kind} in-span"
tally = defaultdict(lambda: [0, 0, 0])
for r, members in roots.items():
    fam = family(members[0]); forced = r in bad; tally[fam][0] += 1; tally[fam][1] += forced; tally[fam][2] += len(members)
print(f"{'family':22s} {'orbits':>7s} {'forced 0':>9s} {'free':>5s} {'coords':>7s}")
tot = [0, 0, 0]
for fam in ["W1 probe in-span", "W1 probe off-span", "W1 cue in-span", "W1 cue off-span", "W2 probe column", "W2 cue column", "readout"]:
    o, f, n = tally[fam]; print(f"{fam:22s} {o:7d} {f:9d} {o - f:5d} {n:7d}"); tot[0] += o; tot[1] += f; tot[2] += n
print(f"{'total':22s} {tot[0]:7d} {tot[1]:9d} {tot[0] - tot[1]:5d} {tot[2]:7d}")
# describe the free orbits of a few families in words (representative + size)
def describe(fam, limit=40):
    print(f"\n{fam}: free orbits (representative, orbit size)")
    for r, members in roots.items():
        if family(members[0]) == fam and r not in bad: print("   ", members[0], len(members))
describe("W1 probe in-span"); describe("readout"); describe("W1 probe off-span"); describe("W1 cue in-span")
